const moveClientStatus = `-- name: MoveClientStatus :one
UPDATE clients
SET status = $1,
    updated_at = now()
WHERE id = $2 AND deleted_at IS NULL
RETURNING id, name, created_at, updated_at, deleted_at, projects_active, portal_users, primary_contact_id, status, account_manager_id, website, phone, address, postal_code, city, country, siret, vat_number
`

type MoveClientStatusParams struct {
	Status string    `json:"status"`
	ID     uuid.UUID `json:"id"`
}

// Deplacement d'une carte du kanban. Distincte de UpdateClient : glisser une
// carte ne doit pas reecrire les coordonnees de l'entreprise avec ce que
// l'ecran avait en memoire.
func (q *Queries) MoveClientStatus(ctx context.Context, arg MoveClientStatusParams) (Client, error) {
	row := q.db.QueryRow(ctx, moveClientStatus, arg.Status, arg.ID)
	var i Client
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.ProjectsActive,
		&i.PortalUsers,
		&i.PrimaryContactID,
		&i.Status,
		&i.AccountManagerID,
		&i.Website,
		&i.Phone,
		&i.Address,
		&i.PostalCode,
		&i.City,
		&i.Country,
		&i.Siret,
		&i.VatNumber,
	)
	return i, err
}

const softDeleteClient = `-- name: SoftDeleteClient :exec
UPDATE clients
SET deleted_at = now(),
    primary_contact_id = NULL,
    updated_at = now()
WHERE id = $1 AND deleted_at IS NULL
`

// Suppression logique, comme partout ailleurs : un client efface par erreur
// doit pouvoir revenir. La designation du contact principal est retiree par la
// meme occasion, sans quoi elle pointerait depuis une ligne morte.
func (q *Queries) SoftDeleteClient(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, softDeleteClient, id)
	return err
}

const updateClient = `-- name: UpdateClient :one
UPDATE clients
SET name               = $1,
    status             = $2,
    account_manager_id = $3,
    website            = $4,
    phone              = $5,
    address            = $6,
    postal_code        = $7,
    city               = $8,
    country            = $9,
    siret              = $10,
    vat_number         = $11,
    updated_at         = now()
WHERE id = $12 AND deleted_at IS NULL
RETURNING id, name, created_at, updated_at, deleted_at, projects_active, portal_users, primary_contact_id, status, account_manager_id, website, phone, address, postal_code, city, country, siret, vat_number
`

